import{_ as a,o,c as s,a2 as i}from"./chunks/framework.DA69LXMH.js";const g=JSON.parse('{"title":"Worldbuilding, Compêndio & Grafos de Conhecimento","description":"","frontmatter":{},"headers":[],"relativePath":"recursos/worldbuilding.md","filePath":"recursos/worldbuilding.md"}'),r={name:"recursos/worldbuilding.md"};function n(t,e,d,l,c,m){return o(),s("div",null,[...e[0]||(e[0]=[i('<h1 id="worldbuilding-compendio-grafos-de-conhecimento" tabindex="-1">Worldbuilding, Compêndio &amp; Grafos de Conhecimento <a class="header-anchor" href="#worldbuilding-compendio-grafos-de-conhecimento" aria-label="Permalink to &quot;Worldbuilding, Compêndio &amp; Grafos de Conhecimento&quot;">​</a></h1><p>O <strong>EchoBot</strong> organiza a história do seu universo de RPG através de ferramentas visuais e semânticas, impedindo que detalhes de tramas, NPCs e conexões de campanha se percam ao longo dos meses.</p><hr><h2 id="🏛️-a-hierarquia-canonica-de-3-niveis" tabindex="-1">🏛️ A Hierarquia Canônica de 3 Níveis <a class="header-anchor" href="#🏛️-a-hierarquia-canonica-de-3-niveis" aria-label="Permalink to &quot;🏛️ A Hierarquia Canônica de 3 Níveis&quot;">​</a></h2><p>Para acomodar crônicas longas e múltiplos grupos jogando no mesmo universo:</p><ol><li><strong>Mundo (World):</strong> O cenário maior (ex: <em>Arton, Faerûn, Golarion</em> ou um cenário caseiro). Guarda as regras do sistema, o compêndio enciclopédico, a árvore de linhagens e o grafo de lore.</li><li><strong>Campanhas (Crônicas):</strong> Aventuras específicas que se passam dentro daquele Mundo (ex: <em>Mesa de Sexta</em>, <em>Mesa de Sábado</em>).</li><li><strong>Sessões:</strong> As partidas individuais de cada campanha, com seus respectivos áudios, transcrições e diários.</li></ol><hr><h2 id="📖-compendio-wiki-de-rpg-integrada" tabindex="-1">📖 Compêndio / Wiki de RPG Integrada <a class="header-anchor" href="#📖-compendio-wiki-de-rpg-integrada" aria-label="Permalink to &quot;📖 Compêndio / Wiki de RPG Integrada&quot;">​</a></h2><p>Organize seu cenário como uma enciclopédia interativa:</p><ul><li><strong>Artigos Categorizados:</strong> Cadastre entidades com atributos específicos nas categorias: <ul><li>👥 <strong>Personagens &amp; NPCs:</strong> Biografia, motivações, alinhamento e papéis.</li><li>📍 <strong>Locais:</strong> Cidades, tavernas, masmorras e reinos.</li><li>⚔️ <strong>Itens &amp; Recompensas:</strong> Artefatos mágicos, armas e relíquias.</li><li>🛡️ <strong>Facções:</strong> Guildas, cultos, ordens de cavalaria e impérios.</li><li>📜 <strong>Conceitos &amp; Lore:</strong> Deuses, magias antigas e eventos históricos.</li></ul></li><li><strong>Segredos do Mestre (GM Secrets):</strong> Cada artigo possui um bloco especial de anotações confidenciais. Informações inseridas nesse bloco <strong>nunca são enviadas para o Portal dos Jogadores</strong>, permanecendo visíveis apenas para o Mestre.</li><li><strong>Sincronização com o Diário Técnico:</strong> Com um único clique, transforme NPCs, locais ou itens descobertos durante uma sessão em artigos permanentes da Wiki.</li><li><strong>Geração de Lore por IA:</strong> Assistente integrado para expandir descrições de cenários e gerar ganchos dramáticos.</li></ul><hr><h2 id="🗺️-grafo-de-conhecimento-interativo-react-flow" tabindex="-1">🗺️ Grafo de Conhecimento Interativo (React Flow) <a class="header-anchor" href="#🗺️-grafo-de-conhecimento-interativo-react-flow" aria-label="Permalink to &quot;🗺️ Grafo de Conhecimento Interativo (React Flow)&quot;">​</a></h2><p>Visualize a teia de relações do seu mundo:</p><ul><li><strong>Nós e Conexões Visuais:</strong> Veja como NPCs se relacionam com facções, quem é rival de quem, quais heróis possuem artefatos e quais locais estão sob cerco.</li><li><strong>Filtros Dinâmicos:</strong> Isole a visualização por tipo de entidade (ex: mostrar apenas <em>Facções e Cidades</em> ou apenas <em>NPCs e Itens</em>).</li><li><strong>Edição de Relacionamentos:</strong> Crie novas conexões diretamente pelo grafo escolhendo o tipo de relação (ex: <em>aliado de, membro de, proprietário de, rival de</em>).</li><li><strong>Persistência 2D:</strong> Arraste e posicione os nós livremente na tela; as coordenadas espaciais são salvas automaticamente no banco de dados.</li></ul><hr><h2 id="👑-linhagens-genealogia-interativa-d3-js" tabindex="-1">👑 Linhagens &amp; Genealogia Interativa (D3.js) <a class="header-anchor" href="#👑-linhagens-genealogia-interativa-d3-js" aria-label="Permalink to &quot;👑 Linhagens &amp; Genealogia Interativa (D3.js)&quot;">​</a></h2><p>Para campanhas de intriga política, famílias nobres ou clãs:</p><ul><li><strong>Organogramas Dinásticos em D3.js:</strong> Navegue por árvores genealógicas colapsáveis com suporte a gerações e casamentos.</li><li><strong>Sugestões de Parentesco por IA:</strong> A IA pode sugerir herdeiros, irmãos ou ancestrais respeitando o tom da campanha.</li></ul><hr><h2 id="🔮-oraculo-semantico-de-mundo-world-rag" tabindex="-1">🔮 Oráculo Semântico de Mundo (World RAG) <a class="header-anchor" href="#🔮-oraculo-semantico-de-mundo-world-rag" aria-label="Permalink to &quot;🔮 Oráculo Semântico de Mundo (World RAG)&quot;">​</a></h2><p>Nunca mais pare a sessão para folhear cadernos antigos:</p><ul><li><strong>Busca Semântica Local:</strong> Pergunte em linguagem natural: <ul><li><em>&quot;Qual era o nome da espada mágica que os jogadores encontraram nas ruínas de Port Coral na 3ª sessão?&quot;</em></li><li><em>&quot;Quais taverneiros conhecem o paradeiro do culto das sombras?&quot;</em></li></ul></li><li><strong>Álgebra Linear Local (NumPy):</strong> A busca calcula similaridade de cosseno em vetores locais, correlacionando o conteúdo de artigos da Wiki, sessões anteriores e transcrições em milissegundos sem enviar seus dados para servidores externos de busca.</li></ul>',22)])])}const p=a(r,[["render",n]]);export{g as __pageData,p as default};
